function write(relative, content) {
  const target = path.join(root, relative);
  const privacySafeContent = content
    .replaceAll("Alexandria Duplex Cleanout", "Alexandria Property Cleanout")
    .replaceAll("Alexandria duplex cleanout", "Alexandria property cleanout")
    .replaceAll("recent local duplex project", "recent local property cleanout");
  const output = relative.endsWith(".html") ? withBasePath(privacySafeContent) : privacySafeContent;
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, output + "\n", "utf8");
}
